import{_ as e,c as r,o as i,ah as h}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"18、【蠱】 巽下艮上","description":"橫渠易說 - 18、【蠱】 巽下艮上","frontmatter":{"title":"18、【蠱】 巽下艮上","description":"橫渠易說 - 18、【蠱】 巽下艮上"},"headers":[],"relativePath":"classics/hengqu/020.md","filePath":"classics/hengqu/020.md"}'),l={name:"classics/hengqu/020.md"};function t(n,a,s,d,c,o){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="_18、【蠱】-巽下艮上" tabindex="-1">18、【蠱】 巽下艮上 <a class="header-anchor" href="#_18、【蠱】-巽下艮上" aria-label="Permalink to “18、【蠱】 巽下艮上”">​</a></h1><h3 id="彖曰-蠱-剛上而柔下-巽而止-蠱。蠱元亨而天下治也-利涉大川-往有事也。-先甲三日-後甲三日-終則有始-天行也。" tabindex="-1">彖曰：蠱，剛上而柔下，巽而止，蠱。蠱元亨而天下治也，“利涉大川”，往有事也。“先甲三日，後甲三日”，終則有始，天行也。 <a class="header-anchor" href="#彖曰-蠱-剛上而柔下-巽而止-蠱。蠱元亨而天下治也-利涉大川-往有事也。-先甲三日-後甲三日-終則有始-天行也。" aria-label="Permalink to “彖曰：蠱，剛上而柔下，巽而止，蠱。蠱元亨而天下治也，“利涉大川”，往有事也。“先甲三日，後甲三日”，終則有始，天行也。”">​</a></h3><p>憂患內萌，蠱之謂也。泰終反否，蠱之體也，弱而止，待能之時也。</p><h3 id="象曰-山下有風-蠱-君子以振民育德。" tabindex="-1">象曰：山下有風，蠱，君子以振民育德。 <a class="header-anchor" href="#象曰-山下有風-蠱-君子以振民育德。" aria-label="Permalink to “象曰：山下有風，蠱，君子以振民育德。”">​</a></h3><p>“後甲三日”，成前事之終；“先甲三日”，善後事之始也。剛上柔下，故可為之唱，是故先甲三日以蠲其法，後甲三日以重其初，明終而復始，通變不窮也。至於巽之九五，以其上下皆柔，故必無初有終，是故先庚後庚，不為物首也。於甲取應物而動，順乎民心也。一本為事之唱。法一作治。</p><h3 id="初六-乾父之蠱-有子-考無咎。厲終吉。-象曰-乾父之蠱-意承考也。" tabindex="-1">初六，乾父之蠱，有子，考無咎。厲終吉。 象曰：“乾父之蠱”，意承考也。 <a class="header-anchor" href="#初六-乾父之蠱-有子-考無咎。厲終吉。-象曰-乾父之蠱-意承考也。" aria-label="Permalink to “初六，乾父之蠱，有子，考無咎。厲終吉。 象曰：“乾父之蠱”，意承考也。”">​</a></h3><p>處下不繫應於上，如子之專制，雖意在承考，然亦危厲，以其柔巽故終吉。</p><h3 id="九二-乾母之蠱-不可貞。-象曰-乾母之蠱-得中道也。" tabindex="-1">九二，乾母之蠱，不可貞。 象曰：“乾母之蠱”，得中道也。 <a class="header-anchor" href="#九二-乾母之蠱-不可貞。-象曰-乾母之蠱-得中道也。" aria-label="Permalink to “九二，乾母之蠱，不可貞。 象曰：“乾母之蠱”，得中道也。”">​</a></h3><p>處中用巽，以剛系柔，乾母之蠱，得剛柔之中也。</p><h3 id="九三-乾父之蠱-小有悔-無大咎。-象曰-乾父之蠱-終無咎也。" tabindex="-1">九三，乾父之蠱，小有悔，無大咎。 象曰：“乾父之蠱”，終無咎也。 <a class="header-anchor" href="#九三-乾父之蠱-小有悔-無大咎。-象曰-乾父之蠱-終無咎也。" aria-label="Permalink to “九三，乾父之蠱，小有悔，無大咎。 象曰：“乾父之蠱”，終無咎也。”">​</a></h3><p>義如初六，小有悔者，以其剛也。</p><h3 id="六四-裕父之蠱-往見-吝。-象曰-裕父之蠱-往未得也。" tabindex="-1">六四，裕父之蠱，往見，吝。 象曰：“裕父之蠱”，往未得也。 <a class="header-anchor" href="#六四-裕父之蠱-往見-吝。-象曰-裕父之蠱-往未得也。" aria-label="Permalink to “六四，裕父之蠱，往見，吝。 象曰：“裕父之蠱”，往未得也。”">​</a></h3><p>“裕父之蠱”，不能為父除患，能寬裕和緩之而已。以柔居陰，失之太柔，故吝。貞固乃可乾事，以柔致遠，往未得也。</p><h3 id="六五-乾父之蠱-用譽。-象曰-乾父用譽-承以德也。" tabindex="-1">六五，乾父之蠱，用譽。 象曰：“乾父用譽”，承以德也。 <a class="header-anchor" href="#六五-乾父之蠱-用譽。-象曰-乾父用譽-承以德也。" aria-label="Permalink to “六五，乾父之蠱，用譽。 象曰：“乾父用譽”，承以德也。”">​</a></h3><p>雖天子必有繼也，故亦云“乾父之蠱”。</p><h3 id="上九-不事王侯-高尚其事。-象曰-不事王侯-志可則也。" tabindex="-1">上九，不事王侯，高尚其事。 象曰：“不事王侯”，志可則也。 <a class="header-anchor" href="#上九-不事王侯-高尚其事。-象曰-不事王侯-志可則也。" aria-label="Permalink to “上九，不事王侯，高尚其事。 象曰：“不事王侯”，志可則也。”">​</a></h3><p>隱居以求其志，故可則也。</p>',17)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
